constraint B != 5;                        % Baker not on 5th
constraint C != 1;                        % Cooper not on 1st
constraint F != 1 /\ F != 5;              % Fletcher not on 1st or 5th
constraint M > C;                         % Miller higher than Cooper
constraint abs(S - F) > 1;                % Smith not adjacent to Fletcher
