% Problem data
int: num_people = 8;
array[1..num_people] of set of int: compatible = [
    {2, 3},    % 1
    {1, 6},    % 2
    {1, 4, 7}, % 3
    {2},       % 4
    {2},       % 5
    {5},       % 6
    {8},       % 7
    {3}        % 8
];

% Decision variables: transplants[i][j] = 1 if person i donates to j
array[1..num_people, 1..num_people] of var 0..1: transplants;

% Constraints
constraint forall(i in 1..num_people, j in 1..num_people where j not in compatible[i]) (
    transplants[i, j] == 0
);

% Each person donates at most once and donation/reception balance
constraint forall(i in 1..num_people) (
    sum([transplants[i, j] | j in 1..num_people]) <= 1
);

constraint forall(i in 1..num_people) (
    sum([transplants[i, j] | j in 1..num_people]) == sum([transplants[k, i] | k in 1..num_people])
);

% Objective: Maximize the number of people receiving kidneys
solve maximize sum([sum([transplants[k, i] | k in 1..num_people]) | i in 1..num_people]);

% Output the transplants matrix as a list of lists
output [
  "["
  ++
  join(",\n ", [
    "[" ++ join(", ", [show(transplants[i, j]) | j in 1..num_people]) ++ "]"
    | i in 1..num_people
  ])
  ++ "]"
];
```

