int: n = 8;
array[1..n] of set of int: adjacency_list = [
    {2, 3, 7},
    {1, 4, 8},
    {1, 4, 5},
    {2, 3, 6},
    {3, 6, 7},
    {4, 5, 8},
    {1, 5, 8},
    {2, 6, 7}
];

array[1..n] of var bool: nodes;

constraint forall(i in 1..n) (
    % Independence constraint: no adjacent nodes are both selected
    forall(j in adjacency_list[i])(nodes[i] + nodes[j] <= 1)
);

constraint forall(i in 1..n) (
    % Maximality constraint: if a node is not selected, at least one neighbor is selected
    (not nodes[i]) -> (sum([nodes[j] | j in adjacency_list[i]]) >= 1)
);

solve satisfy;

output [
    "{\"nodes\": [" ++ join(", ", [show(nodes[i]) | i in 1..n]) ++ "]}" 
];
```

