% Parameters
int: num_jobs = length(machine);
array[1..num_jobs] of array[int] of int: machine;
array[1..num_jobs] of array[int] of int: duration;

% Variables
array[1..num_jobs] of array[int] of var int: start_time;

% Maximum machine ID
int: max_machine = max([machine[j][t] | j in 1..num_jobs, t in 1..length(machine[j])]);

% Precedence constraints within each job
constraint forall(j in 1..num_jobs) (
    forall(t in 1..length(machine[j])-1) (
        start_time[j][t+1] >= start_time[j][t] + duration[j][t]
    )
);

% Machine disjunctive constraints
constraint forall(m in 0..max_machine) (
    let {
        array[int] of var int: starts = [ start_time[j][t] | j in 1..num_jobs, t in 1..length(machine[j]) where machine[j][t] == m ],
        array[int] of int: durations = [ duration[j][t] | j in 1..num_jobs, t in 1..length(machine[j]) where machine[j][t] == m ]
    } in 
    disjunctive(starts, durations)
);

% Calculate makespan
array[1..num_jobs] of var int: job_ends = [ start_time[j][length(machine[j])] + duration[j][length(machine[j])] | j in 1..num_jobs ];
var int: makespan = max(job_ends);

% Objective: minimize makespan
solve minimize makespan;

% Output the result as JSON
output [
    "{\"makespan\": ", show(makespan), "}"
];
```

