constraint circuit(next);

% Calculate total travel distance
var float: travel_distance = sum([dist[i, next[i]] | i in 1..n]);

% Find the optimal tour with minimal distance
solve minimize travel_distance;

% Output the result as JSON
output [
    "{\"travel_distance\": " ++ show_float(0, 2, travel_distance) ++ "}"
];
