enum NAMES = {Agatha, Butler, Charles};

array[NAMES] of string: names = ["Agatha herself", "the butler", "Charles"];

% Decision variables
var 0..2: killer;
array[NAMES, NAMES] of var bool: hate;
array[NAMES, NAMES] of var bool: richer;

% Agatha hates everyone except the butler (herself and Charles)
constraint hate[Agatha, Agatha] = true;
constraint hate[Agatha, Butler] = false;
constraint hate[Agatha, Charles] = true;

% Charles hates no one that Agatha hates (Agatha and Charles)
constraint hate[Charles, Agatha] = false;
constraint hate[Charles, Charles] = false;

% Butler's hates: those not richer than Agatha and everyone Agatha hates
constraint forall(j in NAMES) (hate[Butler, j] <-> (not richer[j, Agatha]));
% Explicitly enforce Butler hates Agatha and Charles (from Agatha's hates)
constraint hate[Butler, Agatha] = true;
constraint hate[Butler, Charles] = true;

% Richer must be irreflexive and antisymmetric
constraint forall(i in NAMES) (richer[i, i] = false);
constraint forall(i, j in NAMES where i != j) (richer[i, j] <-> not richer[j, i]);

% No one hates everyone (at least one non-hate)
constraint forall(i in NAMES) (exists(j in NAMES) (not hate[i, j]));

% Killer must hate Agatha and be no richer than her
constraint hate[killer, Agatha] = true;
constraint not richer[killer, Agatha];

solve satisfy;

% Output the killer's index as specified
output [
    "{", 
    join(",", [
        "\"" ++ "killer" ++ "\": " ++ show(killer)
    ]), 
    "}"
];
