% Parameters
int: n_weeks = 4;
int: n_groups = 3;
int: group_size = 3;
int: n_golfers = n_groups * group_size;

% Decision variables: assign[w, g] = group for golfer g in week w
array[1..n_weeks, 1..n_golfers] of var 1..n_groups: assign;

% Constraints

% Fix first week groups to break symmetry (1-3, 4-6, 7-9)
constraint forall(g in 1..n_golfers) (
    assign[1, g] = ((g - 1) div group_size) + 1
);

% Each group has exactly group_size golfers per week
constraint forall(w in 1..n_weeks, gr in 1..n_groups) (
    count([assign[w, g] | g in 1..n_golfers], gr) = group_size
);

% No two golfers share the same group more than once
constraint forall(g1, g2 in 1..n_golfers where g1 < g2) (
    sum([assign[w, g1] == assign[w, g2] | w in 1..n_weeks]) <= 1
);

% Output the assignments as JSON
output [
  "{\"assign\": [\n    " ++
  join(",\n    ", [
    "[ " ++
    join(", ", [
      "[ " ++ join(", ", [show(g) | g in 1..n_golfers where assign[w, g] == gr ]) ++ " ]"
      | gr in 1..n_groups
    ]) ++ " ]"
    | w in 1..n_weeks
  ]) ++ "\n  ]\n}"
];
