include "globals.mzn";

int: Rows = 8;
int: Cols = 13;

array[1..Rows, 1..Cols] of var 0..1: board;

function tuple(int: num_states, array[int,int] of int: t, int: q0, set of int: qf) nonogram_pattern(array[int] of int: run) =
    let {
        int: run_len = length(run);
        int: num_states = 2 * run_len + 1;
        array[1..num_states, 0..1] of int: t;
        int: q0 = 1;
        set of int: qf = {num_states};
        t = array2d(1..num_states, 0..1, [0 | i in 1..num_states, j in 0..1]);

        % Initial state
        t[1, 0] = 1;  t[1, 1] = 2;

        for (i in 1..run_len) {
            int: s = 2 * i;
            int: len = run[i];
            for (j in 1..len) {
                int: cs = s + j - 1;
                int: ns = if j == len then s + len else cs + 1;
                t[cs, 1] = ns;
            }
            int: ab = s + len;
            t[ab, 0] = ab + 1;
            if i < run_len {
                t[ab+1, 1] = ab + 2;
                t[ab+1, 0] = ab + 1;
            } else {
                t[ab+1, 0] = ab + 1;
            }
        }
    } in (num_states, t, q0, qf);

array[1..Rows] of array[int] of int: row_blocks = [
    [1], [2], [4,4], [12], [8], [9], [3,4], [2,2]
];

array[1..Cols] of array[int] of int: col_blocks = [
    [2], [2,1], [3,2], [6], [1,4], [3], [4], [4], [4], [5], [4], [1,3], [2]
];

predicate nonogram_row(array[int] of var int: x, array[int] of int: blocks) =
    if length(blocks) == 0 then forall(c in x)(c == 0) else
    regular(x, let { tuple(int: ns, array[int,int] of int: t, int: q0, set of int: qf) = nonogram_pattern(blocks) } in (ns, 2, t, q0, qf) endif;

predicate nonogram_col(array[int] of var int: x, array[int] of int: blocks) =
    if length(blocks) == 0 then forall(r in x)(r == 0) else
    regular(x, let { tuple(int: ns, array[int,int] of int: t, int: q0, set of int: qf) = nonogram_pattern(blocks) } in (ns, 2, t, q0, qf) endif;

constraint forall(r in 1..Rows)(nonogram_row([board[r,c] | c in 1..Cols], row_blocks[r]));
constraint forall(c in 1..Cols)(nonogram_col([board[r,c] | r in 1..Rows], col_blocks[c]));

solve satisfy;

output [
    "{",
    "\"board\": [",
    join(",\n", ["[" ++ join(",", [show(board[r,c]) | c in 1..Cols]) ++ "]" | r in 1..Rows]),
    "]",
    "}"
];
