% Input data
int: n_boats = 5;
int: n_periods = 4;
array[1..n_boats] of int: capacity = [6, 8, 12, 12, 12];
array[1..n_boats] of int: crew_size = [2, 2, 2, 2, 4];

% Variables
array[1..n_boats] of var bool: is_host;
array[1..n_boats, 1..n_periods] of var 1..n_boats: visits;

% Constraints

% Hosts stay on their own boat in all periods
constraint forall(h in 1..n_boats where is_host[h]) (
    forall(p in 1..n_periods) (visits[h, p] == h)
);

% Guest boats visit different hosts each period
constraint forall(g in 1..n_boats where not is_host[g]) (
    all_different([visits[g, p] | p in 1..n_periods])
);

% Guests can only visit hosts
constraint forall(g in 1..n_boats where not is_host[g], p in 1..n_periods) (
    is_host[visits[g, p]]
);

% Capacity constraints for each host and period
constraint forall(h in 1..n_boats, p in 1..n_periods where is_host[h]) (
    sum(g in 1..n_boats where not is_host[g]) (crew_size[g] * (visits[g, p] == h)) + crew_size[h] <= capacity[h]
);

% No two guest crews meet more than once
constraint forall(g1, g2 in 1..n_boats where g1 < g2) (
    (not is_host[g1] /\ not is_host[g2]) -> 
        sum(p in 1..n_periods)(visits[g1, p] == visits[g2, p]) <= 1
);

% Objective: minimize number of host boats
solve minimize sum(is_host);

% Output
output [
    "{",
    join(",", [
        "\"is_host\": [" ++ join(",", [show(is_host[b]) | b in 1..n_boats]) ++ "]",
        "\"visits\": [" ++ 
            join(",", [
                "[" ++ join(",", [show(visits[b, p]) | p in 1..n_periods]) ++ "]" 
                | b in 1..n_boats
            ]) ++ 
        "]"
    ]),
    "}"
];
