var 0..9: B;
var 0..9: C;
var 0..9: D;
var 0..9: E;
var 0..9: F;
var 0..9: G;
var 0..9: H;
var 0..9: I;
var 0..9: J;

array[1..20] of var int: add1_letters = [A, E, J, B, B, E, F, C, F, H, A, I, I, J, A, J, J, I, A, B];
array[1..20] of var int: add2_letters = [E, J, E, F, G, A, F, F, I, B, D, I, D, C, B, A, G, F, H, D];
array[1..20] of var int: sum_letters = [F, E, E, H, I, F, B, J, F, A, F, H, D, D, C, A, G, E, J, G];

array[1..20] of var 0..1: carry;

constraint all_different([A,B,C,D,E,F,G,H,I,J]);

constraint B != 0;
constraint D != 0;
constraint G != 0;

constraint carry[20] == 0;

constraint forall(i in 1..20) (
    add1_letters[i] + add2_letters[i] + (if i == 1 then 0 else carry[i-1]) == sum_letters[i] + 10 * carry[i]
);

output [ "{",
    join(",", [
        "\"A\": " ++ show(A),
        "\"B\": " ++ show(B),
        "\"C\": " ++ show(C),
        "\"D\": " ++ show(D),
        "\"E\": " ++ show(E),
        "\"F\": " ++ show(F),
        "\"G\": " ++ show(G),
        "\"H\": " ++ show(H),
        "\"I\": " ++ show(I),
        "\"J\": " ++ show(J)
    ]),
    "}" ];
```

