% Define the array of holes with possible lengths 3, 4, or 5
array[1..18] of var 3..5: holes;

% Constraint: Total length of the course must be 72
constraint sum(holes) = 72;

% Find any valid solution (solver will pick one randomly)
solve satisfy;

% Output the holes array in JSON format
output [
    "{",
    "\"holes\": [" ++ join(", ", [show(holes[h]) | h in 1..18]) ++ "]",
    "}"
];
```

