array[4] of string: warehouse_s = ["New York", "Los Angeles", "Chicago", "Atlanta"];
array[4] of int: fixed_costs = [400, 500, 300, 150];
int: max_shipping = 100;
array[3] of int: demands = [80, 70, 40];
array[4,3] of int: shipping_costs = [|
    20, 40, 50,
    48, 15, 26,
    26, 35, 18,
    24, 50, 35 |];

array[0..3] of var bool: open_warehouse;
array[0..3, 0..2] of var 0..max_shipping: ships;

var int: total_cost = sum(w in 0..3)(fixed_costs[w] * open_warehouse[w]) + 
                      sum(w in 0..3, r in 0..2)(shipping_costs[w, r] * ships[w, r]);

constraint open_warehouse[0] -> open_warehouse[1];
constraint sum(open_warehouse) <= 3;
constraint open_warehouse[1] \/ open_warehouse[3];
constraint forall(r in 0..2)(sum(w in 0..3)(ships[w, r]) >= demands[r]);
constraint forall(w in 0..3)(
    sum(r in 0..2)(ships[w, r]) <= max_shipping * open_warehouse[w]
);

solve minimize total_cost;

output [
    "{",
    join(",", [
        "\"total_cost\": " ++ show(total_cost),
        "\"open_warehouse\": {" ++ 
            join(",", [ "\"" ++ warehouse_s[w] ++ "\": " ++ show(open_warehouse[w]) | w in 0..3 ]) 
            ++ "}",
        "\"ships\": {" ++ 
            join(",", [ 
                "\"" ++ warehouse_s[w] ++ "\": [" ++ 
                join(",", [show(ships[w, r]) | r in 0..2 ]) ++ "]" 
                | w in 0..3 
            ]) ++ "}"
    ]),
    "}"
];
```

