int: num_moves = 3;
array[1..3] of int: init = [1, 0, 1];

array[1..num_moves] of var 1..3: moves;

array[1..3] of var 0..3: counts = [sum([moves[m] == i | m in 1..num_moves]) | i in 1..3];
array[1..3] of var 0..1: final = [(init[i] + counts[i]) mod 2 | i in 1..3];

